  ('289|||רשת הוסטלים לנערות וצעירות במצבי סיכון — ראשון לציון; גישה מודעת טראומה', 289, 'בית_משלך_חכמת_נשים_289', '{"org":"בית משלך (חכמת נשים)","svc":"רשת הוסטלים לנערות וצעירות במצבי סיכון — ראשון לציון; גישה מודעת טראומה","target":"נערות 13–18, צעירות 18–22, ולינה זמנית לצעירות וחיילות בודדות","region":"ראשון לציון","cost":"במימון המשרד לביטחון חברתי","specialty":"","languages":"","diseases":"","notes":"שלוש מסגרות: נערות 13–18 (סמל 12948), צעירות 18–22 (סמל 12926), לינה זמנית לצעירות וחיילות בודדות בוגרות פנימיות או חסרות עורף (סמל 218394). טיפול, קורת גג, ארוחות, לימודים, הכשרה, מיצוי זכויות ותעסוקה. הפניה: נערות דרך חסות הנוער (CRM); צעירות בדו״ח סוציאלי מהמחלקה לשירותים חברתיים. מור הרפז morh@slavpro.co.il · שני ארוך shanis@slavpro.co.il · ציפי נחשון גליק tzipin@wtc-anatgur.co.il. בניהול חכמת נשים וחברת שלו.","tags":"","whatsapp":"","whatsappLabel":"","email":"","web":"https://wtc-anatgur.co.il/%D7%90%D7%95%D7%93%D7%95%D7%AA/%D7%91%D7%99%D7%AA-%D7%9E%D7%A9%D7%9C%D7%9A/","webLabel":"","web2":"","webLabel2":"","add":"","addLabel":"","phone":"052-8511650","phoneLabel":"מור הרפז · צעירות","phoneShowNumber":true,"phone2":"050-9155122","phoneLabel2":"שני ארוך · נערות","phoneShowNumber2":true,"phone3":"050-6223382","phoneLabel3":"ציפי נחשון גליק","phoneShowNumber3":true,"phone4":"","phoneLabel4":"","phoneShowNumber4":true,"phone5":"","phoneLabel5":"","phoneShowNumber5":true,"phone6":"","phoneLabel6":"","phoneShowNumber6":true}'::jsonb, '{"age_min":null,"age_max":null,"sex":"any","location_mode":"any","regions":[],"diagnoses":[],"presenting_problems":[],"recognition":{"btl":"any","moh":"any","mod":"any","rehab_basket":"any"},"internal_notes":""}'::jsonb),
